import { createContext, useState } from "react";

export const ComplaintContext = createContext();

export function ComplaintProvider({ children }) {

  const [complaints, setComplaints] = useState([]);

  const addComplaint = (data) => {
    const severity = detectSeverity(data.desc);

    setComplaints([
      ...complaints,
      {
        id: Date.now(),
        ...data,
        severity,
        status: "Pending",
        timeline: ["Submitted"]
      }
    ]);
  };

  const updateStatus = (id, newStatus) => {
    setComplaints(
      complaints.map((c) =>
        c.id === id
          ? {
              ...c,
              status: newStatus,
              timeline: [...c.timeline, newStatus]
            }
          : c
      )
    );
  };

  /* ⭐ Basic Severity Detection */
  const detectSeverity = (text) => {
    if (!text) return "Low";
    const t = text.toLowerCase();

    if (t.includes("accident") || t.includes("fire") || t.includes("death"))
      return "High";

    if (t.includes("urgent") || t.includes("danger"))
      return "Medium";

    return "Low";
  };

  return (
    <ComplaintContext.Provider
      value={{ complaints, addComplaint, updateStatus }}
    >
      {children}
    </ComplaintContext.Provider>
  );
}
